import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第77章 秋电话","description":"","frontmatter":{},"headers":[],"relativePath":"第77章_秋电话.md","filePath":"第77章_秋电话.md"}'),r={name:"第77章_秋电话.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第77章-秋电话" tabindex="-1">第77章 秋电话 <a class="header-anchor" href="#第77章-秋电话" aria-label="Permalink to &quot;第77章 秋电话&quot;">​</a></h1><p>高三的秋来得很安静。</p><p>风先凉下来，教室窗边的那棵树的叶子，一夜之间就黄了边。早读的时候，空气里有淡淡的潮气，吸进鼻子里，带着一点苦。</p><p>我把外套拉链拉到顶，手指碰到冰凉的金属，心里轻轻抖了一下。</p><p>那段时间，我和江苒的电话，从每周一次，变成了每月一次。</p><p>没有谁先开口，只是自然而然地，时间对不上了。她要排练，要补课，要去她阿婆那边帮忙。我要刷题，要开会，要在夜里把白天的错题再看一遍。</p><p>手机躺在抽屉里，震动都变少了。</p><p>第一次隔了很久才接到她电话，是在一个起风的晚上。</p><p>晚自习结束，教学楼外的路灯亮着，飞蛾绕着光打转。我走回宿舍，鞋底踩在落叶上，发出很轻的碎裂声。口袋里的手机震了一下，我拿出来看，是她。</p><p>我站在路灯底下接起来。</p><p>“喂？”</p><p>那头先是一阵风声，还有她轻轻的呼吸。</p><p>“是我。”她说，“你下课啦？”</p><p>“刚下。”我说，“你那边冷不冷？”</p><p>“冷了。”她笑了一下，“早上出门穿少了，冻得直跺脚。”</p><p>我也笑，肩膀却一下子松下来。好像一整天的紧绷，在听见她声音的那一刻，才找到地方放。</p><p>“最近好吗？”她问。</p><p>“挺好的。”我说，“就是题多，写不完。”</p><p>“别熬太晚。”她说，“你很重要，别熬了。”</p><p>我愣了一下。</p><p>路灯的光落在我手背上，暖黄的一小块。风吹过来，衣领蹭到下巴，有点痒。</p><p>“什么叫我很重要？”我问。</p><p>“就是字面意思。”她很认真，“沈聿，你很重要。你要好好睡觉，好好吃饭，别把自己熬坏了。”</p><p>我喉咙有点紧，说不出话。</p><p>宿舍楼那边传来人声，有人抱着篮球跑过去，鞋底和地面摩擦，吱的一声。远处食堂的窗口还亮着，飘来一点热汤的味道，很淡，一下就被风吹散了。</p><p>“你呢？”我问，“你最近累不累？”</p><p>“我还行。”她说，“就是排练有点多，嗓子有点哑。你听出来了吗？”</p><p>我仔细听，她的声音确实有点沙，尾音轻轻飘着，像被风吹薄的纸。</p><p>“听出来了。”我说，“多喝热水。”</p><p>“你好老派。”她笑出声，咳嗽了两下，又停住，“不过我有听话，保温杯一直带着。”</p><p>“那就好。”</p><p>我们都沉默了一会儿。</p><p>电话里只剩下风声，还有她那边很远的车流声，一波一波的。我能想象她站在走廊上，身后是亮着灯的房间，她把声音放得很轻，不想吵到别人。</p><p>“其实……”她顿了顿，“我有点想你。”</p><p>我的心跳忽然变快，耳朵发热。</p><p>“我也是。”我说。</p><p>说完两个人都笑了，有点不好意思，又有点安心。</p><p>“下个月月末，我们能见一面吗？”她问，“我阿婆说想见见你，给你留了糖。”</p><p>“海盐糖？”我问。</p><p>“对。”她说，“她说你上次喜欢吃，又去买了好多，藏在柜子里，不让别人动。”</p><p>我想起那颗糖的味道，咸咸甜甜的，在舌尖慢慢化开，心里一软。</p><p>“好。”我说，“我去。”</p><p>“那说定了。”她的声音轻快起来，“你别放我鸽子。”</p><p>“不放。”我说，“一定去。”</p><p>又聊了几句，她那边有人喊她的名字，很模糊，隔着门。</p><p>“我得进去了。”她说，“你要记得，晚上早点睡。”</p><p>“知道啦。”我说，“你也是。”</p><p>“沈聿。”她忽然叫我的名字。</p><p>“嗯？”</p><p>“不管以后电话是每周还是每月，你在我这里，都是很重要的。”</p><p>风一下子停了。</p><p>落叶落在我肩上，很轻。我伸手把它拿下来，叶子边缘已经干了，摸起来脆脆的。</p><p>“我知道。”我说，“你也是。”</p><p>她轻轻嗯了一声。</p><p>“挂啦？”她问。</p><p>“你先挂。”我说。</p><p>“不要，你先。”她耍赖。</p><p>我笑起来，眼睛有点酸。</p><p>“好，我数三下，一起挂。”我说。</p><p>“好。”</p><p>我数得很慢，每一下都拖长声音。她在那头小声跟着数，声音混着风，听不太清。</p><p>数完，我们都没挂。</p><p>“你怎么没挂？”她问。</p><p>“你也没挂。”我说。</p><p>两个人都笑，笑着笑着，鼻子都发酸。</p><p>最后还是她先挂的。电话断掉的瞬间，听筒里只剩下一声很轻的忙音，很快就没了。</p><p>我站在路灯下，没动。</p><p>手机屏幕慢慢暗下去，映出我的脸。风又起来了，吹得树叶哗哗响，空气里有泥土的腥气，还有远处飘来的桂花香，很淡很淡。</p><p>我把手机放回口袋，手心出了汗，贴着裤子擦了擦。</p><p>回到宿舍，陈默正坐在床边啃面包，看见我进来，抬头看了一眼。</p><p>“打电话啦？”他问。</p><p>“嗯。”我说。</p><p>“秋天了，电话都变少了吧。”他咬了一口面包，含糊地说，“大家都忙。”</p><p>“是忙。”我说，“但还是会打。”</p><p>“那就好。”他拍拍我肩膀，手上有面包屑，掉在我衣服上，“感情这东西，就怕断了联系。”我低头把那点屑抹掉，布料上还留着一点油光，鼻尖能闻到淡淡的麦香。</p><p>我把面包屑弹掉，坐下来，从抽屉里拿出那枚书签。</p><p>书签边缘已经被摸得发毛，颜色淡了些。我用指腹轻轻蹭了蹭，纸面粗糙的触感让人安心。那点淡蓝在灯下安静地躺着，像退潮后留下的水痕，我看了看又夹回去，怕再翻就把边角碰掉了。</p><p>老周从阳台进来，手里端着盆，热气腾腾的。他看了我一眼，什么也没问，只说了一句。</p><p>“洗洗睡吧，明天还早起。”</p><p>“好。”我说。陈默把剩下的面包用纸包好，笑着说别晾着了明早还要吃，我应了一声，心里还回荡着那句你很重要。</p><p>我拿起床下的暖水袋往阳台走，水房的热水桶还冒着白气。我先把袋口翻开，拧开水龙头试了试，水烫得指尖一缩，又兑了点凉的，再把袋子对着出水口慢慢灌。水流进去时袋身一点点鼓起来，贴着手背发烫，我用手托着袋底轻轻晃了晃，让水匀开，再把气挤出来，拧紧盖子反扣试试不漏，才抱着往回走。袋子暖在怀里，淡淡的橡胶味混着热气扑到下巴上，脚步声在水房的地砖上轻轻响。回到床边把袋子塞进被窝，被面凉凉的，被里很快就有了热度。</p><p>水房的水很凉，泼在脸上，整个人一下子清醒了。镜子里我的眼睛有点红，我用冷水又拍了两下，直到那点红退下去。</p><p>躺到床上，宿舍熄灯了。</p><p>黑暗里，我听见上铺翻身的声音，听见窗外风吹树叶的声音，听见自己很稳的心跳。</p><p>我把手机放在枕头边，调成静音，又忍不住点开，看了一眼通话记录。屏幕光扫到被头的暖水袋，袋面映出一点柔和的光，摸上去烫得恰好，热度从掌心慢慢渗到手指。</p><p>她的名字躺在那里，通话时长很短，却让我觉得，这一整个秋天，都有了着落。</p><p>每月一次也好。</p><p>只要那头的人还在，只要她还记得跟我说，你很重要，别熬了。</p><p>我就觉得，再难的题，再长的夜，都能熬过去。</p><p>暖水袋的热度贴着脚背，慢慢往上走，整个人像是被温水轻轻包住了。迷迷糊糊快睡着的时候，手机又震了一下。</p><p>我摸过来点开，是她发来的一条消息。</p><p>只有短短几个字。</p><p>我盯着那几个字看了很久，心跳又开始变快，睡意全没了。</p><p>窗外的风声忽然变大，像是有什么事情，正跟着这个秋天一起，朝我走来。</p>',94)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
